# checker.py - prints OK for the right flag
import sys

SECRET = [73, 68, 65, 110, 110, 70, 92, 2, 74, 76, 35, 18, 32, 51, 7, 54, 28, 71, 78, 245, 241]

def check(flag):
    if len(flag) != len(SECRET):
        return False
    for i, ch in enumerate(flag):
        if ord(ch) ^ (i * 7 % 256) != SECRET[i]:
            return False
    return True

print("OK" if check(sys.argv[1]) else "NO")
